-- ===== Part 2: row-level security, functions, grants (hand-written) =====
-- Roles pcp_migrator, pcp_app, pcp_scheduler, pcp_rls_definer are created by the
-- bootstrap step (src/bootstrap.ts) before migrations run. Default privileges
-- granted there give pcp_app SELECT/INSERT/UPDATE/DELETE on new tables.

-- Tenant context helpers. Values are transaction-local (set_config(..., true)).
CREATE FUNCTION pcp_current_org() RETURNS uuid
  LANGUAGE sql STABLE
  AS $$ SELECT NULLIF(current_setting('app.organization_id', true), '')::uuid $$;

CREATE FUNCTION pcp_current_user() RETURNS uuid
  LANGUAGE sql STABLE
  AS $$ SELECT NULLIF(current_setting('app.user_id', true), '')::uuid $$;

GRANT EXECUTE ON FUNCTION pcp_current_org() TO pcp_app, pcp_scheduler, pcp_rls_definer;
GRANT EXECUTE ON FUNCTION pcp_current_user() TO pcp_app, pcp_scheduler, pcp_rls_definer;

-- organizations: the row itself is the tenant.
ALTER TABLE "organizations" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "organizations" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "organizations"
  USING (id = pcp_current_org())
  WITH CHECK (id = pcp_current_org());

-- Every other tenant table is isolated by organization_id.
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['organization_members', 'invitations', 'products', 'environments', 'teams', 'audit_logs']
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I USING (organization_id = pcp_current_org()) WITH CHECK (organization_id = pcp_current_org())',
      t
    );
  END LOOP;
END
$$;

-- Audit log is append-only for the application.
REVOKE UPDATE, DELETE, TRUNCATE ON "audit_logs" FROM pcp_app;

-- The application never touches migration bookkeeping. (The table is absent in
-- Prisma's shadow database, hence the guard.)
DO $$
BEGIN
  IF to_regclass('public._prisma_migrations') IS NOT NULL THEN
    REVOKE ALL ON "_prisma_migrations" FROM pcp_app, pcp_scheduler;
  END IF;
END
$$;

-- Narrow cross-tenant lookups. Owned by pcp_rls_definer (BYPASSRLS, NOLOGIN), so
-- they can read across tenants; they return only what the caller is entitled to.

-- Memberships of one user, for login and context switching.
CREATE FUNCTION pcp_user_memberships(p_user uuid)
  RETURNS TABLE (
    organization_id uuid,
    organization_name text,
    role member_role,
    all_products boolean,
    product_ids uuid[]
  )
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = public, pg_temp
  AS $$
    SELECT m.organization_id, o.name, m.role, m.all_products, m.product_ids
    FROM organization_members m
    JOIN organizations o ON o.id = m.organization_id
    WHERE m.user_id = p_user
    ORDER BY o.name
  $$;

-- Invitation lookup by token hash (the invitee is not yet a member).
CREATE FUNCTION pcp_find_invitation(p_token_hash text)
  RETURNS TABLE (
    id uuid,
    organization_id uuid,
    email text,
    role member_role,
    all_products boolean,
    product_ids uuid[],
    expires_at timestamptz,
    accepted_at timestamptz
  )
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = public, pg_temp
  AS $$
    SELECT i.id, i.organization_id, i.email, i.role, i.all_products, i.product_ids, i.expires_at, i.accepted_at
    FROM invitations i
    WHERE i.token_hash = p_token_hash
  $$;

-- Organization of a product, only when p_user is a member of it; NULL otherwise.
CREATE FUNCTION pcp_resolve_product_org(p_product uuid, p_user uuid)
  RETURNS uuid
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = public, pg_temp
  AS $$
    SELECT p.organization_id
    FROM products p
    JOIN organization_members m ON m.organization_id = p.organization_id AND m.user_id = p_user
    WHERE p.id = p_product
  $$;

-- Organization of an environment, only when p_user is a member of it; NULL otherwise.
CREATE FUNCTION pcp_resolve_environment_org(p_environment uuid, p_user uuid)
  RETURNS uuid
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = public, pg_temp
  AS $$
    SELECT e.organization_id
    FROM environments e
    JOIN organization_members m ON m.organization_id = e.organization_id AND m.user_id = p_user
    WHERE e.id = p_environment
  $$;

DO $$
DECLARE
  f text;
BEGIN
  FOREACH f IN ARRAY ARRAY[
    'pcp_user_memberships(uuid)',
    'pcp_find_invitation(text)',
    'pcp_resolve_product_org(uuid, uuid)',
    'pcp_resolve_environment_org(uuid, uuid)'
  ]
  LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO pcp_rls_definer', f);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', f);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO pcp_app', f);
  END LOOP;
END
$$;
